ragraph -->\n                <tr>\n                  <td class=\"mobile-p-24\" style=\"padding: 0 40px 24px 40px;\">\n                    <p style=\"margin: 0; font-size: 15px; line-height: 24px; color: #475569;\">\n                      Hallo <strong>{{CustomerName}}</strong>, we hebben je offerteaanvraag ontvangen voor bestelling #<strong>{{ShortOrderId}}</strong>. Ons engineeringteam beoordeelt je bestanden, analyseert de printgeometrie en stelt je offerte op maat samen.\n                    </p>\n                  </td>\n                </tr>\n\n                \n                \n\n                <!-- Call To Action Button -->\n                <tr>\n                  <td class=\"mobile-p-24\" align=\"center\" style=\"padding: 8px 40px 24px 40px;\">\n                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"mobile-full-width\">\n                      <tr>\n                        <td align=\"center\" style=\"background-color: #f8fafc; border: 1px solid #cbd5e1; border-radius: 12px; box-shadow: 0 2px 4px rgba(19, 56, 39, 0.15);\">\n                          <a href=\"{{OrderUrl}}\" target=\"_blank\" style=\"display: block; padding: 13px 28px; font-size: 14px; font-weight: 700; color: #1e293b; text-decoration: none; letter-spacing: 0.3px;\">\n                            Bestelstatus Bekijken &rarr;\n                          </a>\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                </tr>\n\n                \n                  <!-- Direct Link Row -->\n  <tr>\n    <td class=\"mobile-p-20\" align=\"center\" style=\"padding: 0 40px 24px 40px;\">\n      <p style=\"margin: 0; font-size: 12px; line-height: 18px; color: #94a3b8; word-break: break-all;\">\n        Directe link: <a href=\"{{OrderUrl}}\" style=\"color: #059669; text-decoration: underline;\">{{OrderUrl}}</a>\n      </p>\n    </td>\n  </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- Footer Information -->\n          <tr>\n            <td align=\"center\" style=\"padding: 32px 24px 0 24px;\">\n              <p style=\"margin: 0 0 8px 0; font-size: 13px; line-height: 20px; color: #64748b;\">\n                Vragen over je 3D-print of bestelspecificaties?<br />\n                Neem contact op met ons engineeringteam via <a href=\"mailto:info@printmy3d.work\" style=\"color: #133827; font-weight: 600; text-decoration: underline;\">info@printmy3d.work</a>\n              </p>\n              <p style=\"margin: 0; font-size: 12px; line-height: 18px; color: #94a3b8;\">\n                &copy; Print My 3D &bull; Precision Additive Manufacturing &bull; Rotterdam, NL\n              </p>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>",
