"{{LogoUrl}}\" width=\"36\" height=\"36\" alt=\"Print My 3D\" style=\"display: block; border: 0;\" />\n                    </td>\n                    <td style=\"vertical-align: middle;\">\n                      <span style=\"font-size: 20px; font-weight: 800; color: #133827; letter-spacing: -0.5px;\">Print My 3D</span>\n                    </td>\n                  </tr>\n                </table>\n              </a>\n            </td>\n          </tr>\n\n          <!-- Main Card Container -->\n          <tr>\n            <td style=\"background-color: #ffffff; border-radius: 16px; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03); border: 1px solid #e2e8f0; overflow: hidden;\">\n              <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\n                <!-- Card Header with Badge -->\n                <tr>\n                  <td class=\"mobile-p-24\" align=\"center\" style=\"padding: 40px 40px 24px 40px;\">\n                    \n                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n                      <tr>\n                        <td style=\"background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 9999px; padding: 4px 16px;\">\n                          <span style=\"color: #334155; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.2px; display: inline-block;\">\n                            Güvenlik &bull; Hesap\n                          </span>\n                        </td>\n                      </tr>\n                    </table>\n                    <h1 class=\"mobile-h1\" style=\"margin: 18px 0 0 0; font-size: 26px; font-weight: 800; color: #0f172a; letter-spacing: -0.5px; line-height: 34px;\">\n                      Şifrenizi Sıfırlayın\n                    </h1>\n                  </td>\n                </tr>\n\n                <!-- Intro Paragraph -->\n                <tr>\n                  <td class=\"mobile-p-24\" style=\"padding: 0 40px 24px 40px;\">\n                    <p style=\"margin: 0; font-size: 15px; line-height: 24px; color: #475569;\">\n                      Merhaba <strong>{{CustomerName}}</strong>, şifrenizi sıfırlama talebi aldık. Yeni bir şifre seçmek için aşağıdaki butona tıklayın. Bu talebi siz yapmadıysanız, bu e-postayı güvenle yok sayabilirsiniz.\n                    </p>\n                  </td>\n                </tr>\n\n                \n                \n\n                <!-- Call To Action Button -->\n                <tr>\n                  <td class=\"mobile-p-24\" align=\"center\" style=\"padding: 8px 40px 24px 40px;\">\n                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"mobile-full-width\">\n                      <tr>\n                        <td align=\"center\" style=\"background-color: #133827; border: 1px solid #0d261a; border-radius: 12px; box-shadow: 0 2px 4px rgba(19, 56, 39, 0.15);\">\n                          <a href=\"{{ResetLink}}\" target=\"_blank\" style=\"display: block; padding: 16px 36px; font-size: 16px; font-weight: 700; color: #ffffff; text-decoration: none; letter-spacing: 0.3px;\">\n                            Şifremi Sıfırla &rarr;\n                          </a>\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                </tr>\n\n                  <tr>\n    <td class=\"mobile-p-20\" align=\"center\" style=\"padding: 12px 40px 0 40px;\">\n      <p style=\"margin: 0; font-size: 12px; line-height: 18px; color: #94a3b8;\">\n        Bu şifre sıfırlama bağlantısının süresi 2 saat içinde dolar. Bu talebi siz yapmadıysanız herhangi bir işlem yapmanız gerekmez.\n      </p>\n    </td>\n  </tr>\n                \n              </table>\n            </td>\n          </tr>\n\n          <!-- Footer Information -->\n          <tr>\n            <td align=\"center\" style=\"padding: 32px 24px 0 24px;\">\n              <p style=\"margin: 0 0 8px 0; font-size: 13px; line-height: 20px; color: #64748b;\">\n                3D baskınız veya sipariş özellikleriniz hakkında sorularınız mı var?<br />\n                Mühendislik ekibimizle şu adresten iletişime geçin: <a href=\"mailto:info@printmy3d.work\" style=\"color: #133827; font-weight: 600; text-decoration: underline;\">info@printmy3d.work</a>\n              </p>\n              <p style=\"margin: 0; font-size: 12px; line-height: 18px; color: #94a3b8;\">\n                &copy; Print My 3D &bull; Precision Additive Manufacturing &bull; Rotterdam, NL\n              </p>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>",
