/tr>\n\n          <!-- Footer Information -->\n          <tr>\n            <td align=\"center\" style=\"padding: 32px 24px 0 24px;\">\n              <p style=\"margin: 0 0 8px 0; font-size: 13px; line-height: 20px; color: #64748b;\">\n                3D baskınız veya sipariş özellikleriniz hakkında sorularınız mı var?<br />\n                Mühendislik ekibimizle şu adresten iletişime geçin: <a href=\"mailto:info@printmy3d.work\" style=\"color: #133827; font-weight: 600; text-decoration: underline;\">info@printmy3d.work</a>\n              </p>\n              <p style=\"margin: 0; font-size: 12px; line-height: 18px; color: #94a3b8;\">\n                &copy; Print My 3D &bull; Precision Additive Manufacturing &bull; Rotterdam, NL\n              </p>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>",
